<section class="page-heading department-heading"><div class="shell"><p class="eyebrow"><?=View::escape(View::setting($siteContent??[],'research.projects_eyebrow','Research in action'))?></p><h1><?=View::escape(View::setting($siteContent??[],'research.projects_title','Research projects'))?></h1><p class="lead"><?=View::escape(View::setting($siteContent??[],'research.projects_intro','Discover ongoing, planned, and completed FAST research and innovation projects.'))?></p></div></section><section class="section"><div class="shell"><form class="public-search" method="get" action="<?=View::escape($baseUrl)?>research/projects"><label for="project-directory-search">Find a project</label><div><input id="project-directory-search" name="q" type="search" maxlength="100" value="<?=View::escape($search)?>" placeholder="Title or subject"><select name="status" aria-label="Project status"><option value="">All project statuses</option><?php foreach($statuses as$status):?><option value="<?=$status?>"<?=$statusFilter===$status?' selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select><button class="button button-primary" type="submit">Search</button></div></form><?php if($result['items']===[]):?><div class="public-empty"><h2><?=$search===''&&$statusFilter===''?View::escape(View::setting($siteContent??[],'research.projects_title','Project pages are being prepared')):'No projects found'?></h2><p>Published research projects will appear here.</p></div><?php else:?><div class="department-card-grid"><?php foreach($result['items']as$p):?><?php $image=$media($p['hero_path']);?><article class="department-card"><?php if($image):?><img src="<?=View::escape($image)?>" alt="<?=View::escape($p['hero_alt_text']?:$p['title'])?>"><?php endif;?><div><p class="eyebrow"><?=View::escape(ucfirst($p['project_status']))?> project</p><h2><a href="<?=View::escape($baseUrl)?>research/projects/<?=View::escape($p['slug'])?>"><?=View::escape($p['title'])?></a></h2><p><?=View::escape(mb_strimwidth((